import { Accessor, createSignal, onCleanup, onMount, Setter } from "solid-js";

/**
 * Track the engine ready status globally.
 */
let engineIsReady = false;

/**
 * Create a cancelleable engine event registration.
 * This internally ensures that engine.whenReady is resolved.
 * `clear` *must* be called in order to unregister the event.
 */
function registerEngineEvent(name: string, callback: (...args: unknown[]) => void): EventHandle {
	if (engineIsReady) {
		engine.on(name, callback);
		return {
			clear: () => engine.off(name, callback),
		};
	} else {
		let isRegistered = false;
		let isCancelled = false;
		engine.whenReady.then(() => {
			engineIsReady = true;

			if (!isCancelled) {
				engine.on(name, callback);
			}
			isRegistered = true;
		});

		return {
			clear: () => {
				if (isRegistered) {
					engine.off(name, callback);
				} else {
					isCancelled = true;
				}
			},
		};
	}
}

let debugWidgetUpdatedEventHandle: EventHandle | null = null;
let debugWidgetEventRefCount = 0;

const widgetRegistry = new Map<string, { getter: Accessor<UIDebugWidgetValue>; setter: Setter<UIDebugWidgetValue> }>();

function handleDebugWidgetUpdated(id: string, value: UIDebugWidgetValue) {
	const entry = widgetRegistry.get(id);
	if (entry) {
		entry.setter(value);
	}
}

/**
 * Creates a signal from an existing debug widget.
 * @param id The id of the widget.  If a widget doesn't exist, a signal will still be created.
 * @returns The signal accessor for when the widget's value has changed.
 */
export function createSignalFromExistingDebugWidget(id: string) {
	let entry = widgetRegistry.get(id);
	if (entry == null) {
		const [getter, setter] = createSignal<UIDebugWidgetValue>(UI.Debug.getWidgetValue(id));
		entry = { getter, setter };
		widgetRegistry.set(id, entry);
	}

	onMount(() => {
		debugWidgetEventRefCount++;

		if (debugWidgetEventRefCount == 1) {
			debugWidgetUpdatedEventHandle = registerEngineEvent("DebugWidgetUpdated", handleDebugWidgetUpdated);
		}
	});

	onCleanup(() => {
		debugWidgetEventRefCount--;

		if (debugWidgetEventRefCount == 0) {
			debugWidgetUpdatedEventHandle?.clear();
			debugWidgetUpdatedEventHandle = null;
		}
	});

	return entry.getter;
}

/**
 * Registers a debug widget and returns a signal accessor for when that widget's value changes.
 * NOTE: The widget will be deleted on cleanup.
 * @param widget The definition of the widget
 * @returns The signal accessor for when the widget's value has changed.
 */
export function createSignalFromDebugWidget(widget: UIDebugWidgetDefinition) {
	onMount(() => {
		UI.Debug.registerWidget(widget);

		onCleanup(() => {
			UI.Debug.deleteWidget(widget.id);
		});
	});

	return createSignalFromExistingDebugWidget(widget.id);
}
